import{_ as a,o,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"অধ্যায় 106 | স্তর পরিমার্জন · সংবেদনা-মূল স্তর · লুণ্ঠনপক্ষ বনাম সহজীবনপক্ষ তুলনা","description":"","frontmatter":{"title":"অধ্যায় 106 | স্তর পরিমার্জন · সংবেদনা-মূল স্তর · লুণ্ঠনপক্ষ বনাম সহজীবনপক্ষ তুলনা","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","路线对比"],"related":["04-掠夺式修炼体系批判","01-衡元宙核心世界观","14-修炼境界统一划分"]},"headers":[],"relativePath":"bn/106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"bn/106_模块1-感元境-掠夺派vs共生派对比.md"}'),d={name:"bn/106_模块1-感元境-掠夺派vs共生派对比.md"};function u(l,t,i,q,h,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="অধ্যায়-106-সংবেদনা-মূল-স্তর-লুণ্ঠনপক্ষ-ও-সহজীবনপক্ষের-ব্যবস্থাগত-তুলনা" tabindex="-1">অধ্যায় 106 | সংবেদনা-মূল স্তর: লুণ্ঠনপক্ষ ও সহজীবনপক্ষের ব্যবস্থাগত তুলনা <a class="header-anchor" href="#অধ্যায়-106-সংবেদনা-মূল-স্তর-লুণ্ঠনপক্ষ-ও-সহজীবনপক্ষের-ব্যবস্থাগত-তুলনা" aria-label="Permalink to &quot;অধ্যায় 106 | সংবেদনা-মূল স্তর: লুণ্ঠনপক্ষ ও সহজীবনপক্ষের ব্যবস্থাগত তুলনা&quot;">​</a></h1><blockquote><p>মডিউল: মডিউল এক · স্তরসমূহের গভীর পরিমার্জন | ভিত্তি নথি: 04, 01, 14</p></blockquote><h2 id="ভূমিকা-দুটি-সাধনা-যুক্তি-দুই-প্রকার-বিশ্ব" tabindex="-1">ভূমিকা: দুটি সাধনা-যুক্তি, দুই প্রকার বিশ্ব <a class="header-anchor" href="#ভূমিকা-দুটি-সাধনা-যুক্তি-দুই-প্রকার-বিশ্ব" aria-label="Permalink to &quot;ভূমিকা: দুটি সাধনা-যুক্তি, দুই প্রকার বিশ্ব&quot;">​</a></h2><p>সংবেদনা-মূল স্তর কেবল সাধনার সূচনা নয়, বিশ্বদৃষ্টির প্রথম সড়কদ্বীপও: প্রথম শক্তি-শোষণ থেকেই সাধক দ্বি-মুখী মোড়ে দাঁড়িয়ে—হয় &quot;আমি বিশ্ব থেকে নিই&quot;, নয় &quot;আমি বিশ্বের সাথে বাড়ি&quot;। দুই বাক্য কাছাকাছি শোনায়, কিন্তু দুটো সম্পূর্ণ ভিন্ন বিশ্বে নিয়ে যায়: একটি শিকারক্ষেত্র যেখানে সবল দুর্বলকে খায়; আরেকটি জীবন-সম্প্রদায় যেখানে সব প্রাণী একসাথে উঠে যায়।</p><p>এই প্রবন্ধ লুণ্ঠনমূলক সাধনা পদ্ধতি ও নোঙর সহজীবী সভ্যতার ব্যবস্থা-স্তরের তুলনা দেয়।</p><p>ছয়টি শীর্ষ স্বতঃসিদ্ধই বিভাজক রেখা: অপহরণবিরোধী স্বতঃসিদ্ধ &quot;নেওয়া&quot; আর &quot;বাড়া&quot;-কে আলাদা করে; হাজারো জাতি গণতান্ত্রিক স্বতঃসিদ্ধ &quot;কেবল আমার জাতি&quot; আর &quot;সব জাতি&quot;-কে আলাদা করে; সমষ্টিগত মাত্রিক উন্নতি স্বতঃসিদ্ধ &quot;আমি একা উঠি&quot; আর &quot;আমরা একসাথে উঠি&quot;-কে আলাদা করে; কার্যকারণ আত্ম-শৃঙ্খলা স্বতঃসিদ্ধ &quot;ঋণ অন্যত্র&quot; আর &quot;আমি নিজের ফল ভোগ করি&quot;-কে আলাদা করে; নিয়ম অগ্রাধিকার স্বতঃসিদ্ধ &quot;আমার সুবিধার নিয়ম&quot; আর &quot;স্থিতিশীল স্ব-সঙ্গত বিধি&quot;-কে আলাদা করে। সমস্ত প্রাণীর জন্য সর্বজনীন অসীম সমতার আইন প্রতিষ্ঠা করে যে প্রত্যেক প্রাণী মৌলিক অসীম শক্তি সহজাতভাবে ধারণ করে: আলস্যপ্রবণ ব্যক্তি নিশ্চিত ন্যূনতম অসীম বজায় রাখে এবং যুগের দ্বারা নিষ্কাশিত হবে না, অপরদিকে পরিশ্রমী ও কিশোর সর্বোচ্চগণ উচ্চতর স্তরের অসীম সঞ্চয় করতে পারে। অসীম মূল সবার সহজাত; লুণ্ঠনবাদী যুক্তির &quot;কেবল সবলই বাঁচতে পারে&quot; মুখেই অবৈধ।</p><h2 id="এক-ব্যবস্থাগত-তুলনার-মুখ্য-সারণি" tabindex="-1">এক. ব্যবস্থাগত তুলনার মুখ্য সারণি <a class="header-anchor" href="#এক-ব্যবস্থাগত-তুলনার-মুখ্য-সারণি" aria-label="Permalink to &quot;এক. ব্যবস্থাগত তুলনার মুখ্য সারণি&quot;">​</a></h2><table tabindex="0"><thead><tr><th>মাত্রা</th><th>লুণ্ঠনপক্ষ</th><th>সহজীবনপক্ষ (নোঙর)</th></tr></thead><tbody><tr><td>শক্তির উৎস</td><td>অন্যের মূল গিলে ফেলে</td><td>বিশ্বচক্র থেকে নেয়, ফেরত দেয়</td></tr><tr><td>দুর্বলদের প্রতি মনোভাব</td><td>প্রাকৃতিক ছাঁকনি, দুর্বল মরুক</td><td>সবার জন্য রেলিং, একজনকেও বাদ নয়</td></tr><tr><td>সিলিং-যুক্তি</td><td>কবরস্থানের ওপরে এক শিখর</td><td>সমষ্টি একসাথে ওঠে</td></tr><tr><td>সময়-দিগন্ত</td><td>এখন টেনে, পরে ফেলে দাও</td><td>দ্বি-মুখী চক্র, টিকিয়ে রাখা যায়</td></tr><tr><td>ঝুঁকির মনোভাব</td><td>ঝুঁকি ছাঁকনি</td><td>ঝুঁকি সমাধানযোগ্য সমস্যা</td></tr><tr><td>নৈতিক ভিত্তি</td><td>বলবানই ধর্ম</td><td>কার্যকারণ আত্ম-শৃঙ্খলা</td></tr><tr><td>চূড়ান্ত গন্তব্য</td><td>এক নক্ষত্র-অঞ্চলের অধিপতি</td><td>সামঞ্জস্যপূর্ণ নোঙর অতি-বহুল স্তর</td></tr></tbody></table><h2 id="দুই-লুণ্ঠনপক্ষের-তিনটি-ভ্রান্তি" tabindex="-1">দুই. লুণ্ঠনপক্ষের তিনটি ভ্রান্তি <a class="header-anchor" href="#দুই-লুণ্ঠনপক্ষের-তিনটি-ভ্রান্তি" aria-label="Permalink to &quot;দুই. লুণ্ঠনপক্ষের তিনটি ভ্রান্তি&quot;">​</a></h2><ol><li>শূন্য-যোগ ভ্রান্তি: বিশ্বাস যে শক্তি স্থির, তাই নিতে হলে অন্যের কাছ থেকে ছিনিয়ে নিতে হবে—অন্ধ এই সত্যে যে বিশ্বচক্রের শক্তি পুনর্জন্মযোগ্য ও প্রসারণযোগ্য।</li><li>প্রাকৃতিক ছাঁকনি ভ্রান্তি: বিশ্বাস যে দুর্বলরা ছাঁকনির যোগ্য—অন্ধ এই সত্যে যে আলস্যপ্রবণদের ন্যূনতম অসীম ধীরেরা পিষ্ট না হয়ে সাথে চলতে দেয়।</li><li>&quot;প্রজ্ঞাবান লুণ্ঠনকারী&quot; ভ্রান্তি: বিশ্বাস যে দয়ালু লুণ্ঠনকারীই শ্রেষ্ঠ লুণ্ঠনকারী—অন্ধ এই সত্যে যে লুণ্ঠনের গঠনই রোগ, লুণ্ঠনকারীর স্বভাব নয়।</li></ol><h2 id="তিন-প্রজ্ঞাবান-লুণ্ঠনকারী-ও-ঐতিহাসিক-পশ্চাদপসরণ" tabindex="-1">তিন. &quot;প্রজ্ঞাবান লুণ্ঠনকারী&quot; ও ঐতিহাসিক পশ্চাদপসরণ <a class="header-anchor" href="#তিন-প্রজ্ঞাবান-লুণ্ঠনকারী-ও-ঐতিহাসিক-পশ্চাদপসরণ" aria-label="Permalink to &quot;তিন. &quot;প্রজ্ঞাবান লুণ্ঠনকারী&quot; ও ঐতিহাসিক পশ্চাদপসরণ&quot;">​</a></h2><p>তথাকথিত প্রজ্ঞাবান লুণ্ঠনকারী—অর্থাৎ সেই সবল যে অনায়াসে মারে না, দুর্বলদের সাথে &quot;কিছু ভাগ করে&quot;, নিজেকে দয়ালু বলে ডাকে—লুণ্ঠনপক্ষের সবচেয়ে বিপজ্জনক আত্ম-ভ্রম। দয়ালু শিকারী এখনো শিকারী; তার দয়া কেবল তার শিকার-ব্যবস্থাপনার পরিমার্জন। ইতিহাস বারবার দেখায় লুণ্ঠনবাদী ব্যবস্থার &quot;প্রজ্ঞাবান&quot; যুগ সবসময় পশ্চাদগমনের প্রাক্কাল: শিকারক্ষেত্র শেষ হলে, &quot;দয়ালু&quot; সবলরাই প্রথম নিজের লোকদের ওপর ফিরে যায়।</p><h2 id="চার-ধর্মীয়-বদমাশ-মনোনীত-দের-জন্য-সতর্কতা" tabindex="-1">চার. ধর্মীয় বদমাশ: &quot;মনোনীত&quot;-দের জন্য সতর্কতা <a class="header-anchor" href="#চার-ধর্মীয়-বদমাশ-মনোনীত-দের-জন্য-সতর্কতা" aria-label="Permalink to &quot;চার. ধর্মীয় বদমাশ: &quot;মনোনীত&quot;-দের জন্য সতর্কতা&quot;">​</a></h2><p>সহজীবনপক্ষ এমন ভান করে না যে তার নিজের পক্ষ নিখুঁত। সবচেয়ে ছলনাময়ী রূপটি হলো &quot;ধর্মীয় বদমাশ&quot;: যে ন্যায়ের চাদর পরে নামলেও লুটপাট করে, বলে &quot;এটি আমি সহজীবনের জন্য করছি&quot;, অথচ নিজের উত্তরণের জন্য অন্যদের শোষণ করে।</p><p>এই বিশ্বের নায়ক লিন হাও-কে কসৌটি হিসেবে নিন: তার পথ শিকারক্ষেত্রের সবলতম হওয়া নয়, বরং প্রমাণ করা যে সবল উঠতে পারে অথচ দুর্বলদের ঘরে ফেরার পথ রেখে দিতে পারে। যতবার সে &quot;আমি বিশেষ, তাই নিয়ম আমার ওপর খাটে না&quot; বলতে প্রলুব্ধ হয়, ঠিক সেই মুহূর্তেই সংক্ষিপ্ত-পথের অন্তরাত্মা-দানব কড়া নাড়ে—সহজীবনপক্ষের প্রত্যেক সাধকের এই অন্তররেখা বজায় রাখা আবশ্যক।</p><h2 id="পাঁচ-পাঁচটি-মূল-স্থল" tabindex="-1">পাঁচ. পাঁচটি মূল স্থল <a class="header-anchor" href="#পাঁচ-পাঁচটি-মূল-স্থল" aria-label="Permalink to &quot;পাঁচ. পাঁচটি মূল স্থল&quot;">​</a></h2><ul><li>শক্তি-স্তর অপচয় বিরোধ: লুণ্ঠনপক্ষের &quot;সবল দুর্বলকে খায়&quot; যেকোনো যুদ্ধের চেয়ে বেশি বিবর্তনীয় সম্ভাবনা নষ্ট করে; সহজীবনপক্ষের দ্বি-মুখী চক্রই প্রকৃত উচ্চ-দক্ষতা।</li><li>অপহরণ বিরোধ: মুখ্য সারণির প্রতিটি সারি লাল রেখা যা সহজীবনপক্ষ মাড়াবে না।</li><li>তাং লুও সিলিং তুলনা: লুণ্ঠনপক্ষের সিলিং কবরস্থানের ওপর এক অধিপতি; সহজীবনপক্ষের সিলিং গোটা বিশ্বকে তুলে নেয়।</li><li>হাজারো জাতি পূর্ণ আচ্ছাদন: মুখ্য সারণি শক্তির উৎস থেকে চূড়ান্ত গন্তব্য পর্যন্ত প্রতিটি মাত্রা ঢেকে ফেলেছে, কোনো অন্ধকোণ নেই।</li><li>অতি-বহুলবাদ পূর্ণ উন্মুক্তি: তুলনাটাই উন্মুক্ত প্রমাণ—লুণ্ঠনপক্ষ এটা ছাপাতে সাহস পায় না, কারণ প্রতিটি মাত্রা তার নিজের ক্ষুদ্রতা প্রকাশ করে দেয়।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সারণির অলংকরণের দরকার নেই; দুটো স্তম্ভ নিজেই কথা বলে। সংবেদনা-মূল স্তরে সাধক যে প্রথম শোষণ বেছে নেয়, সেটাই বেঁচে থাকার বাকি জীবন সে কোন স্তম্ভে দাঁড়াবে তা ঠিক করে—এই কারণেই এই তুলনা গোটা গ্রন্থাগারের একদম শুরুতে রাখা হয়েছে: পথ বেছে নেওয়ার আগে প্রত্যেক পাঠক যেন দেখে নেয় সে কোন বিশ্বে ঢুকতে যাচ্ছে।</p><h2 id="সংশ্লিষ্ট" tabindex="-1">সংশ্লিষ্ট <a class="header-anchor" href="#সংশ্লিষ্ট" aria-label="Permalink to &quot;সংশ্লিষ্ট&quot;">​</a></h2><ul><li>সংশ্লিষ্ট নথি: <a href="./04-掠夺式修炼体系批判">04-লুণ্ঠনমূলক সাধনা পদ্ধতির সমালোচনা</a> · <a href="./01-衡元宙核心世界观">01-হেং ইয়ানঝোউ-এর মূল বিশ্বদৃষ্টি</a> · <a href="./14-修炼境界统一划分">14-সাধনা স্তরের একীভূত বিভাজন</a></li><li>অফিসিয়াল সাইট: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',21)])])}const c=a(d,[["render",u]]);export{_ as __pageData,c as default};
